from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination.

    Coins of different denominations are not combined. The inputs are a
    nonempty list of positive denominations and a positive, one-based rank.
    The input list is not modified.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # A denomination divisible by a smaller one adds no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    low, high = denominations[0], denominations[0] * k

    # Inclusion-exclusion counts the union of the multiples. Aggregate
    # subsets with the same LCM, since they share the same floor(x / LCM).
    # LCMs above the search bound never contribute and can be discarded.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = lcm(multiple, coin)
            if common <= high:
                changes[common] = changes.get(common, 0) - coefficient
        for multiple, change in changes.items():
            coefficient = coefficients.get(multiple, 0) + change
            if coefficient:
                coefficients[multiple] = coefficient
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    while low < high:
        midpoint = (low + high) // 2
        count = sum(coefficient * (midpoint // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = midpoint
        else:
            low = midpoint + 1
    return low
